// MTBF
fetch events
| filter matchesPhrase(event.name, "sre_endpoint_monitoring_event_for_availability") AND isNotNull(dt.entity.service.name)
| filter endpoint.name == "/api/v1/security-filters/ds-ms-dr-lg-transactional-loan/payment-quota"

| makeTimeseries problems_created = countIf(event.status_transition == "CREATED", default:0), by:{dt.entity.service, endpoint.name}, nonempty:true, interval:1h
| fieldsAdd acumulative = arrayCumulativeSum(problems_created)
| fieldsAdd reverse_acumulative = acumulative[]*-1 + arrayMax(acumulative)

// se calcula la suma de todos los intervalos
| fieldsAdd sum_interval = if(acumulative[] == arrayMax(acumulative) or reverse_acumulative[] == arrayMax(acumulative), 0, else:1)
| fieldsRemove acumulative, reverse_acumulative

// se calcula la cantidad de intervalos = total de fallas -1
| fieldsAdd intervalos = arraySum(problems_created)-1

// se aplica MTBF = (Σ intervalos entre fallas) / (nº de intervalos)
| fields MTBF = ( arraySum(sum_interval) )/ (intervalos)

